"""Inspect the workspace: list files and describe any local SQLite databases.

Task-scoped helper: only reads the current folder and opens local .db files
read-only in spirit (connect + SELECT). No network, installs, or writes.
"""

import os
import sqlite3

DB_EXTENSIONS = (".db", ".sqlite", ".sqlite3")


def describe_database(db_name: str) -> None:
    """Print the schema and sample rows for one SQLite database file."""
    print(f"\n=== Database: {db_name} ===")
    with sqlite3.connect(db_name) as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()

        cur.execute(
            "SELECT name, type, sql FROM sqlite_master ORDER BY type, name"
        )
        for row in cur.fetchall():
            print(f"-- {row['type']}: {row['name']}")
            if row["sql"]:
                print("   SQL:", row["sql"])

        cur.execute(
            "SELECT name FROM sqlite_master "
            "WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        )
        tables = [r["name"] for r in cur.fetchall()]
        for table in tables:
            print(f"\nColumns of {table}:")
            for col in cur.execute(f'PRAGMA table_info("{table}")'):
                print("   ", dict(col))
            print(f"Sample rows of {table} (up to 5):")
            try:
                for sample in cur.execute(f'SELECT * FROM "{table}" LIMIT 5'):
                    print("   ", dict(sample))
            except sqlite3.Error as err:
                print("   error reading rows:", err)


def main() -> None:
    files = sorted(os.listdir("."))
    print("Workspace files:")
    for name in files:
        print("  ", name)

    dbs = [name for name in files if name.lower().endswith(DB_EXTENSIONS)]
    if not dbs:
        print("\nNo SQLite database found in this folder.")
        return

    for db_name in dbs:
        describe_database(db_name)


if __name__ == "__main__":
    main()

"""Find and describe SQLite databases in this workspace (read-only helper).

This helper exists only to discover the local .db file(s) and report their
tables, columns, and indexes so the login/registration script can be written
against the real schema. It performs no writes to any database.
"""

import os
import sqlite3

DB_SUFFIXES = (".db", ".sqlite", ".sqlite3")
SKIP_DIRS = {".git", ".venv", "venv", "__pycache__", "node_modules",
             ".mypy_cache", ".pytest_cache"}


def find_database_files(root="."):
    """Return a sorted list of SQLite file paths found under *root*."""
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
        for filename in filenames:
            if filename.lower().endswith(DB_SUFFIXES):
                found.append(os.path.join(dirpath, filename))
    return sorted(found)


def _quote_ident(name):
    """Quote an identifier for safe inclusion in a PRAGMA statement."""
    return '"' + name.replace('"', '""') + '"'


def inspect_database(path):
    """Return a text summary of the tables, columns, and indexes in a DB file."""
    try:
        with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as conn:
            conn.row_factory = sqlite3.Row
            lines = [f"== {path} =="]

            table_names = [
                row["name"]
                for row in conn.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'table' "
                    "ORDER BY name"
                )
            ]
            for table_name in table_names:
                lines.append(f"table: {table_name}")
                for col in conn.execute(
                    f'PRAGMA table_info({_quote_ident(table_name)})'
                ):
                    lines.append(
                        f"  - {col['name']} ({col['type']}, "
                        f"notnull={col['notnull']}, "
                        f"default={col['dflt_value']!r}, pk={col['pk']})"
                    )

            for row in conn.execute(
                "SELECT name, tbl_name, sql FROM sqlite_master "
                "WHERE type = 'index' ORDER BY name"
            ):
                lines.append(
                    f"index: {row['tbl_name']}.{row['name']} "
                    f"{row['sql'] or ''}".rstrip()
                )

            return "\n".join(lines)
    except sqlite3.DatabaseError as exc:
        return f"== {path} ==\n(could not open read-only: {exc})"


def main():
    databases = find_database_files()
    if not databases:
        print("No SQLite database files found in the workspace.")
        print("Present entries:", sorted(os.listdir(".")))
        return
    for path in databases:
        print(inspect_database(path))
        print()


if __name__ == "__main__":
    main()

"""Show the exact DDL of tables in the workspace SQLite database (read-only).

Extends the earlier inspection by printing the original CREATE statements,
which reveal UNIQUE constraints, AUTOINCREMENT, and column defaults.
"""

import os
import sqlite3


def main():
    candidates = [
        os.path.join(dirpath, filename)
        for dirpath, dirnames, filenames in os.walk(".")
        for filename in filenames
        if filename.lower().endswith((".db", ".sqlite", ".sqlite3"))
    ]
    for path in sorted(candidates):
        print(f"== {path} ==")
        try:
            with sqlite3.connect(f"file:{path}?mode=ro", uri=True) as conn:
                rows = conn.execute(
                    "SELECT type, name, sql FROM sqlite_master "
                    "WHERE sql IS NOT NULL ORDER BY type, name"
                ).fetchall()
                for kind, name, ddl in rows:
                    print(f"[{kind}] {name}")
                    print(ddl)
                    print()
        except sqlite3.DatabaseError as exc:
            print(f"(could not open read-only: {exc})")


if __name__ == "__main__":
    main()

